import re

def calistir(program: str):
    # Atamaları ve ifadeleri ayırmak için bölümler
    lines = program.splitlines()

    # Değişkenlerin saklandığı sözlük
    degiskenler = {}

    # Son ifadeyi tutmak için değişken
    son_ifade = None

    for line in lines:
        # Yorum satırı varsa ayır
        line = line.split('#')[0].strip()
        if not line:  # Boş satır
            continue

        # İfadeleri ';' ile ayır
        ifadeler = [f for f in re.split(r'\s*;\s*', line) if f]

        for ifade in ifadeler:
            try:
                son_ifade = deger_ata(ifade, degiskenler)
            except Exception as e:
                raise e

    return son_ifade

def deger_ata(ifade: str, degiskenler: dict):
    # Atama işlemi mi?
    if '=' in ifade:
        parts = re.split(r'\s*=\s*', ifade, 1)
        if len(parts) != 2:
            raise SyntaxError("Geçersiz atama")

        ad = parts[0].strip()
        deger_ifadesi = parts[1].strip()

        # Değişken ismi kontrolü
        if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', ad):
            raise SyntaxError("Geçersiz değişken adı")

        deger = hesapla(deger_ifadesi, degiskenler)
        degiskenler[ad] = deger
        return deger

    else:
        # Sadece ifadeyse değerini döndür
        return hesapla(ifade, degiskenler)

def hesapla(ifade: str, degiskenler: dict):
    ifade = ifade.strip()
    if not ifade:
        raise SyntaxError("Boş ifade")

    # Parantezleri çöz
    while '(' in ifade:
        match = re.search(r'\([^()]+\)', ifade)
        if not match:
            raise SyntaxError("Geçersiz parantez")

        inner_expr = match.group(0)[1:-1]
        inner_result = hesapla(inner_expr, degiskenler)
        ifade = ifade[:match.start()] + str(inner_result) + ifade[match.end():]

    # Fonksiyonlar
    if re.match(r'^abs\([^)]+\)$', ifade):
        match = re.match(r'^abs\(([^)]+)\)$', ifade)
        val = hesapla(match.group(1), degiskenler)
        return abs(val)

    elif re.match(r'^min\([^)]*(?:,[^)]*)*\)$', ifade):
        match = re.match(r'^min\((.*)\)$', ifade)
        args_str = match.group(1).strip()
        if not args_str:
            raise SyntaxError("Min fonksiyonu için argüman yok")

        args = [arg.strip() for arg in re.split(r',(?![^(]*[)])', args_str)]
        parsed_args = [hesapla(arg, degiskenler) for arg in args]
        return min(parsed_args)

    elif re.match(r'^max\([^)]*(?:,[^)]*)*\)$', ifade):
        match = re.match(r'^max\((.*)\)$', ifade)
        args_str = match.group(1).strip()
        if not args_str:
            raise SyntaxError("Max fonksiyonu için argüman yok")

        args = [arg.strip() for arg in re.split(r',(?![^(]*[)])', args_str)]
        parsed_args = [hesapla(arg, degiskenler) for arg in args]
        return max(parsed_args)

    # Aritmetik ifadeler için ayrıştırma
    tokens = tokenize(ifade)
    result = evaluate_tokens(tokens, degiskenler)
    return result

